rule.definition:
if(
  a!isNullOrEmpty(ri!recordTypeUuid),
  #"SYSTEM_SYSRULES_httpResponse_v1"(
    statusCode: 400,
    headers: {
      #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
    },
    body: #"SYSTEM_SYSRULES_toJson_v1"(
      a!map(
        success: false,
        error: "MISSING_PARAMETER",
        message: "recordType UUID is required"
      )
    )
  ),
  a!localVariables(
    local!recordTypeRef: eval(concat("recordType!{", ri!recordTypeUuid, "}")),
    local!properties: a!recordTypeProperties(recordType: local!recordTypeRef),
    if(
      a!isNullOrEmpty(local!properties.recordType.fields),
      #"SYSTEM_SYSRULES_httpResponse_v1"(
        statusCode: 404,
        headers: {
          #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
        },
        body: #"SYSTEM_SYSRULES_toJson_v1"(
          a!map(
            success: false,
            error: "RECORD_TYPE_NOT_FOUND",
            message: "No record type found for UUID: " & ri!recordTypeUuid
          )
        )
      ),
      a!localVariables(
        local!selectedFieldRefs: if(
          a!isNullOrEmpty(ri!selectedFields),
          {},
          #"SYSTEM_SYSRULES_forEach"(
            items: ri!selectedFields,
            expression: displayvalue(
              fv!item,
              local!properties.recordType.fields.name,
              local!properties.recordType.fields.reference,
              null
            )
          )
        ),
        local!filterExpressions: if(
          a!isNullOrEmpty(ri!filters),
          {},
          #"SYSTEM_SYSRULES_forEach"(
            items: ri!filters,
            expression: #"SYSTEM_SYSRULES_queryFilter"(
              field: displayvalue(
                fv!item.field,
                local!properties.recordType.fields.name,
                local!properties.recordType.fields.reference,
                null
              ),
              operator: fv!item.operator,
              value: fv!item.value
            )
          )
        ),
        local!sortField: if(
          a!isNullOrEmpty(ri!pagingInfo.sort.field),
          {},
          #"SYSTEM_SYSRULES_sortInfo"(
            field: displayvalue(
              ri!pagingInfo.sort.field,
              local!properties.recordType.fields.name,
              local!properties.recordType.fields.reference,
              null
            ),
            ascending: a!defaultValue(ri!pagingInfo.sort.ascending, true)
          )
        ),
        local!paging: #"SYSTEM_SYSRULES_pagingInfo"(
          startIndex: a!defaultValue(ri!pagingInfo.startIndex, 1),
          batchSize: a!defaultValue(ri!pagingInfo.batchSize, 10),
          sort: local!sortField
        ),
        local!data: #"SYSTEM_SYSRULES_queryRecordType_v4"(
          recordType: local!recordTypeRef,
          fields: local!selectedFieldRefs,
          filters: local!filterExpressions,
          pagingInfo: local!paging,
          fetchTotalCount: true
        ),
        #"SYSTEM_SYSRULES_httpResponse_v1"(
          statusCode: 200,
          headers: {
            #"SYSTEM_SYSRULES_httpHeader"(name: "Content-Type", value: "application/json")
          },
          body: #"SYSTEM_SYSRULES_toJson_v1"(
            a!map(
              success: true,
              totalCount: local!data.totalCount,
              data: local!data.data
            )
          )
        )
      )
    )
  )
)
